        reason_complex_reaction_product: "반응 생성물(UVCB)은 하나의 물질로 판단할 수 없어 미확정으로 분류합니다. 폐액 배치에서 실제 조성을 확인해 주세요.",
        reason_heavy_metal: "분자식에 중금속 또는 규제성 금속(Ag, Cd, Pb, Hg, Cr, As, Ni, Cu, Zn, Ba, Co, Mn, Tl, Pd, Pt, Sn 등)이 포함되어 있습니다.",
