        mix_reason_organic_solvent_context: "선택한 용매가 비할로겐성 유기용매이므로 실제 폐액은 비할로겐족 유기 폐액 흐름으로 보정합니다.",
        mix_reason_halogen_solute_context: "비할로겐 용매를 선택했지만 용질 자체가 할로겐 유기물입니다. 보수적으로 할로겐족 유기 폐액으로 분류합니다.",
